function quitGame():
	music("stop")
	remove blindness from {actor}
	loop all fake entities:
		kill fake entity loop-value
	clear {actor}
	clear {-timer}
	clear {-beatlinesummoned::*}
	clear {pause}
	clear all players' inventory
	stop all sounds for all players
	clear {-note::*}
	loop all interactions:
		delete loop-entity
	loop all block displays:
		delete loop-entity
	loop all text displays:
		delete loop-entity
	set {combo} to 0
	set {maxNote} to 0
	set {-noteID} to 0
	set {score} to 0
	set {hitNotes} to 0
	clear {beat}
	clear {statistics::*}
	clear {playing}
