            then:
                if parse tags contains "same":
                    continue
            else if parse tags contains "different":
                continue
        else:
            loop exprs-1:
                if {_x} is not set:
                    set {_x} to x of loop-value
                    set {_z} to z of loop-value
                else:
                    if x of loop-value is not {_x}:
                        if parse tags contains "different":
                            continue
                    else if z of loop-value is not {_z}:
                        if parse tags contains "different":
                            continue
                    else:
                        if parse tags contains "same":
                            continue

function mtskr_nodeLoc(string: string, world: world) :: location:
    set {_v::*} to {_string} parsed as "%integer%,%integer%,%integer%"
    return block at location({_v::1}, {_v::2}, {_v::3}, {_world})

function mtskr_message(lang: string, key: string, replace: objects = "none", with: objects = "none") :: string:
    if yaml "MTskR.lang.%{_lang}%" is not loaded:
        set {_lang} to "en_us"
    set {_string} to yaml value {_key} of "MTskR.lang.%{_lang}%"
    if {_string} is not set:
        set {_string} to yaml value {_key} of "MTskR.lang.en_us"
    if {_replace::*} is not "none":
        loop {_replace::*}:
            add 1 to {_i}
            set {_replace} to join "%%%loop-value%%%"
            set {_with} to "%{_i}th element of {_with::*}%"
            replace {_replace} with {_with} in {_string}
    replace "%%nl%%" with nl in {_string}
    regex replace "(?<!\\)\\n" with nl in {_string}
    return {_string}

function mtskr_removeRail(l1: string, l2: string, world: world):
    set {_yaml} to "MTskR.data.rails.%{_world}%"
    set {_type} to yaml value "%{_l1}%.%{_l2}%.type" of {_yaml}
    if {_type} is "siding":
        mtskr_stopRoute({_world}, "%{_l1}%.%{_l2}%")
        set {_armorstands::*} to armor stands within mtskr_nodeLoc({_l1}, {_world}) and mtskr_nodeLoc({_l2}, {_world})
        loop {_armorstands::*}:
            if metadata tag "mtskr.train_id" of loop-value is set:
                remove entity loop-value
    if yaml node "%{_l1}%.%{_l2}%" of {_yaml} exists:
        delete yaml value "%{_l1}%.%{_l2}%" of {_yaml}
        if yaml node keys {_l1} of {_yaml} is not set:
            delete yaml value {_l1} of {_yaml}
    if yaml node "%{_l2}%.%{_l1}%" of {_yaml} exists:
        delete yaml value "%{_l2}%.%{_l1}%" of {_yaml}
        if yaml node keys {_l2} of {_yaml} is not set:
            delete yaml value {_l2} of {_yaml}
    save yaml {_yaml} without extra lines between nodes

